@pytest.mark.parametrize("method", list(EXPECTED))
def test_each_engineering_row_has_named_computation_and_distinct_metric(method):
    row,key=EXPECTED[method]; result=run_engineering_method(method,VALID[method])
    assert result["row"]==row and result["method"]==method and result["feasible"] is True
    assert key in result and isinstance(result[key],(int,float,bool))
    assert METHODS[method].__name__==method and METHOD_INPUTS[method]

@pytest.mark.parametrize("method", list(EXPECTED))
def test_each_engineering_row_rejects_missing_method_specific_input(method):
    bad=dict(VALID[method]); bad.pop(METHOD_INPUTS[method][0])
    with pytest.raises(EngineeringMethodError,match="missing required inputs"): run_engineering_method(method,bad)

def test_distinctive_rows_and_safety_fail_closed():
    assert run_engineering_method("message_queue",VALID["message_queue"])["utilization"]==.5
    assert run_engineering_method("ab_testing",VALID["ab_testing"])["absolute_lift"]==pytest.approx(.2)
    assert run_engineering_method("computer_vision",VALID["computer_vision"])["intersection_over_union"]==.5
    assert run_engineering_method("optimization_engine",VALID["optimization_engine"])["objective_improvement"]==2
    with pytest.raises(EngineeringMethodError,match="unsafe overload"): run_engineering_method("message_queue",{"arrival_rate":10,"service_rate":5})
    with pytest.raises(EngineeringMethodError,match="image geometry"): run_engineering_method("computer_vision",{"intersection_area":11,"union_area":10})
    with pytest.raises(EngineeringMethodError,match="infeasible"): run_engineering_method("optimization_engine",{"objective_before":1,"objective_after":2,"constraint_violations":1})
    with pytest.raises(EngineeringMethodError,match="unsafe key"): run_engineering_method("encryption",{"key_bits":64,"min_key_bits":128})
